    let wp;

    for (wp = worn; cptr.ldI64(wp); wp = cptr.add(wp, 1, 24))
        if (cptr.ldI64(wp) & wornmask)
            return cptr.ldPtr(cptr.ldPtro(wp, $worn_w_obj));
