        if (!creation &&
                (cptr.ldI32o(best, $obj_lamplit) & 1) | 0 &&
                ((cptr.ld1uo(
                    cptr.ldPtro(
                        cptr.ldPtro(gv, $instance_globals_v_viz_array),
                        cptr.ldI16o(mon, $monst_my),
                        8
                    ),
                    cptr.ldI16o(mon, $monst_mx)
                ) &
                    NHM.IN_SIGHT) != 0)) {
            let adesc = arti_light_description(best);

            if (sawmon)
                (yield* pline(__s_s_s_to_shine_s, (yield* Yname2(best)), (yield* otense(best, __s_begin)), adesc));
            else if (canseemon(mon))
                (yield* pline(__s_s_s_shining_s, (yield* Yname2(best)), (yield* otense(best, __s_are)), adesc));
            else if (sawloc)
                (yield* pline(
                    __s_s_begins_to_shine_s,
                    cptr.ldPtro(c_common_strings, $c_common_strings_c_Something),
                    adesc
                ));
            else
                (yield* pline(
                    __s_s_is_shining_s,
                    cptr.ldPtro(c_common_strings, $c_common_strings_c_Something),
                    adesc
                ));
        }
